mapper.select:
/* StatMapper.selectAuctionStatListCount 옥션 정산/통계 목록 갯수 */
SELECT COUNT(*) FROM ( SELECT RESULT_DATE, TABLE_CODE FROM (
SELECT RESULT_DATE AS RESULT_DATE
SELECT SUBSTRING(RESULT_DATE, 1, 8) AS RESULT_DATE
SELECT SUBSTRING(RESULT_DATE, 1, 6) AS RESULT_DATE
SELECT SUBSTRING(RESULT_DATE, 1, 4) AS RESULT_DATE
, TABLE_CODE FROM T_MSG_STAT
WHERE TABLE_CODE = #{tableCode}
WHERE TABLE_CODE IN
#{code}
) STAT_A WHERE RESULT_DATE >= #{startDate} AND RESULT_DATE <= #{endDate} GROUP BY RESULT_DATE, TABLE_CODE ) STAT_B

/* StatMapper.selectAuctionStatList 옥션 정산/통계 목록 조회 */
SELECT RESULT_DATE, TABLE_CODE, SUM(SUCC_CNT) AS SUCC_CNT, SUM(TRY_CNT) AS TRY_CNT, (SUM(TRY_CNT) - SUM(SUCC_CNT)) AS FAIL_CNT , SUM(FAIL_00) AS FAIL_00, SUM(FAIL_01) AS FAIL_01, SUM(FAIL_02) AS FAIL_02, SUM(FAIL_03) AS FAIL_03, SUM(FAIL_04) AS FAIL_04 , SUM(FAIL_05) AS FAIL_05, SUM(FAIL_06) AS FAIL_06, SUM(FAIL_07) AS FAIL_07, SUM(FAIL_08) AS FAIL_08, SUM(FAIL_09) AS FAIL_09 , #{companyCode} AS COMPANY_CODE FROM (
SELECT RESULT_DATE AS RESULT_DATE
SELECT SUBSTRING(RESULT_DATE, 1, 8) AS RESULT_DATE
SELECT SUBSTRING(RESULT_DATE, 1, 6) AS RESULT_DATE
SELECT SUBSTRING(RESULT_DATE, 1, 4) AS RESULT_DATE
, TABLE_CODE, SUCC_CNT, TRY_CNT , FAIL_00, FAIL_01 , FAIL_02, FAIL_03, FAIL_04 , FAIL_05, FAIL_06, FAIL_07, FAIL_08, FAIL_09 FROM T_MSG_STAT
WHERE TABLE_CODE = #{tableCode}
WHERE TABLE_CODE IN
#{code}
) T WHERE RESULT_DATE >= #{startDate} AND RESULT_DATE <= #{endDate} GROUP BY RESULT_DATE, TABLE_CODE
ORDER BY
${s.selector}
DESC ASC
ORDER BY RESULT_DATE DESC, TABLE_CODE

/* StatMapper.selectStatListGmarketCount G마켓 정산/통계 목록 갯수 */
SELECT COUNT(*) FROM ( SELECT RESULT_DATE, TABLE_CODE, TABLE_NAME FROM (
SELECT A.RESULT_DATE AS RESULT_DATE
SELECT SUBSTRING(A.RESULT_DATE, 1, 8) AS RESULT_DATE
SELECT SUBSTRING(A.RESULT_DATE, 1, 6) AS RESULT_DATE
SELECT SUBSTRING(A.RESULT_DATE, 1, 4) AS RESULT_DATE
, A.TABLE_CODE, B.TABLE_NAME FROM T_MSG_STAT A JOIN T_TCODE_LIST B ON A.TABLE_CODE = B.TABLE_CODE WHERE B.COMPANY_CODE = 1
AND B.TABLE_CODE = #{tableCode}
) STAT_A WHERE RESULT_DATE >= #{startDate} AND RESULT_DATE <= #{endDate} GROUP BY RESULT_DATE, TABLE_CODE, TABLE_NAME ) STAT_B
